struct Entity {                                   // the hook
    virtual ~Entity() = default;
    virtual void update(float dt) = 0;
};
struct Guard : Entity {
    float x = 0;
    void update(float dt) override { x += 20.f * dt; }
};

std::vector<std::unique_ptr<Entity>> entities;    // the collection
for (auto& e : entities) e->update(dt);           // the driver walk

